// Sobol 低差异序列的方向数表。从 scipy.stats.qmc.Sobol 导出（unscrambled），
// 经 Base64 编码后内联到 HTML，避免外部文件依赖。
// 每个维度 30 个方向数，每个方向数为 32-bit 无符号整数
const SOBOL_B64='';

const SOBOL_DIMS=756,SOBOL_BITS=30,SOBOL_SCALE=1/Math.pow(2,SOBOL_BITS);
// ====== 解码方向数表为 Uint32Array ======
// 从 Base64 字符串解码为 32-bit 无符号整数数组，供 Sobol 序列生成使用
let SOBOL_DIRS;
(function(){const b=atob(SOBOL_B64);const a=new Uint32Array(SOBOL_DIMS*SOBOL_BITS);for(let i=0;i<a.length;i++){a[i]=(b.charCodeAt(i*4)|(b.charCodeAt(i*4+1)<<8)|(b.charCodeAt(i*4+2)<<16)|(b.charCodeAt(i*4+3)<<24))>>>0}SOBOL_DIRS=a})();

// ====== Sobol 序列生成 (增量 Gray code) ======
// 用 Gray code 增量法生成低差异 Sobol 序列。每个样本用前一个 XOR 方向数得到下一个，
// 避免全量重新计算。序列长度取 2^k（k = ceil(log2(nPaths))），保证低差异性质。
function sobolGenerate(nPaths,d){
const pts=new Float64Array(nPaths*d);
const cur=new Uint32Array(d);
for(let i=1;i<nPaths;i++){
let n=i,c=0;while((n&1)===0){n>>=1;c++}
for(let j=0;j<d;j++){cur[j]^=SOBOL_DIRS[j*SOBOL_BITS+c];pts[i*d+j]=cur[j]*SOBOL_SCALE}
}
return pts;
}

// ====== Acklam 正态逆CDF ======
// Acklam 有理函数近似法计算标准正态逆 CDF（ppf）。
// 最大误差 < 1.15e-9，比 Box-Muller 方法更精确且用等距 Sobol 点映射无失真。
function normPpf(p){
if(p<=0)return-Infinity;if(p>=1)return Infinity;
const a=[-3.969683028665376e+01,2.209460984245205e+02,-2.759285104469687e+02,1.383577518672690e+02,-3.066479806614716e+01,2.506628277459239e+00];
const b=[-5.447609879822406e+01,1.615858368580409e+02,-1.556989798598866e+02,6.680131188771972e+01,-1.328068155288572e+01];
const c=[-7.784894002430293e-03,-3.223964580411365e-01,-2.400758277161838e+00,-2.549732539343734e+00,4.374664141464968e+00,2.938163982698783e+00];
const d=[7.784695709041462e-03,3.224671290700398e-01,2.445134137142996e+00,3.754408661907416e+00];
const pl=0.02425,ph=1-pl;let q,r;
if(p<pl){q=Math.sqrt(-2*Math.log(p));return((((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1))}
else if(p<=ph){q=p-0.5;r=q*q;return((((((a[0]*r+a[1])*r+a[2])*r+a[3])*r+a[4])*r+a[5])*q)/(((((b[0]*r+b[1])*r+b[2])*r+b[3])*r+b[4])*r+1)}
else{q=Math.sqrt(-2*Math.log(1-p));return-((((((c[0]*q+c[1])*q+c[2])*q+c[3])*q+c[4])*q+c[5])/((((d[0]*q+d[1])*q+d[2])*q+d[3])*q+1))}
}

// ====== 正态随机数 (Sobol → ppf) ======
// 生成 nPaths×nSteps 标准正态随机数矩阵。
// 用 Sobol 均匀序列经 Acklam ppf 变换为正态分布，保证低差异性质传递到正态空间。
function generateNormals(nPaths,nSteps){
let m=Math.ceil(Math.log2(Math.max(nPaths,2)));let total=Math.pow(2,m);
const sobol=sobolGenerate(total,nSteps);
const out=new Float64Array(nPaths*nSteps);
for(let i=0;i<nPaths;i++)for(let j=0;j<nSteps;j++){let u=Math.max(1e-10,Math.min(1-1e-10,sobol[i*nSteps+j]));out[i*nSteps+j]=normPpf(u)}
return out;
}

// ====== 带缓存的 Sobol 序列生成 ======
// 缓存键：sobol_${nPaths}_${nSteps}
// 缓存值：Float64Array 序列化为 base64
// 策略：只缓存 ≤ 2MB 的序列（避免 localStorage 溢出，8192×504×8≈33MB 不缓存）
// localStorage 不可用时（如 Node.js 环境）静默降级到 generateNormals
const SOBOL_CACHE_PREFIX = 'sobol_';
const SOBOL_CACHE_MAX = 3;
const SOBOL_CACHE_MAX_BYTES = 2 * 1024 * 1024; // 2MB

function getCachedNormals(nPaths, nSteps) {
    const key = SOBOL_CACHE_PREFIX + nPaths + '_' + nSteps;
    const byteLen = nPaths * nSteps * 8;
    const cacheable = byteLen <= SOBOL_CACHE_MAX_BYTES;

    if (cacheable) {
        try {
            const cached = localStorage.getItem(key);
            if (cached) {
                const binary = atob(cached);
                const bytes = new Uint8Array(binary.length);
                for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
                return new Float64Array(bytes.buffer);
            }
        } catch (e) {
            // localStorage 不可用或缓存损坏，静默降级
        }
    }

    // 缓存未命中或不可缓存，生成新序列
    const normals = generateNormals(nPaths, nSteps);

    if (cacheable) {
        try {
            const bytes = new Uint8Array(normals.buffer);
            let binary = '';
            for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
            const base64 = btoa(binary);
            localStorage.setItem(key, base64);
            cleanupSobolCache(key);
        } catch (e) {
            // localStorage 满或不可用，静默降级
        }
    }

    return normals;
}

function cleanupSobolCache(keepKey) {
    const keys = [];
    for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (k && k.startsWith(SOBOL_CACHE_PREFIX) && k !== keepKey) {
            keys.push(k);
        }
    }
    // 保留最近添加的（简化：按 key 顺序删除最早的，使总数不超过 SOBOL_CACHE_MAX）
    while (keys.length >= SOBOL_CACHE_MAX) {
        localStorage.removeItem(keys.shift());
    }
}

export { sobolGenerate, normPpf, generateNormals, getCachedNormals, SOBOL_DIMS, SOBOL_BITS };
